//! Parity test: the ported `rdbwselect` (scoped option set) vs R.
//! Cases come from `fixtures/bandwidth.json` and are regenerated by `tools/parity.py`.

use std::fs;
use std::path::PathBuf;

use rdrobust_core::{rdbwselect, Kernel, Vce};
use serde::Deserialize;

#[derive(Deserialize)]
struct Expected {
    h_l: f64,
    h_r: f64,
    b_l: f64,
    b_r: f64,
}

#[derive(Deserialize)]
struct Fixture {
    id: String,
    x: Vec<f64>,
    y: Vec<f64>,
    #[serde(default)]
    t: Option<Vec<f64>>,
    c: f64,
    p: usize,
    q: usize,
    deriv: usize,
    kernel: String,
    vce: String,
    scaleregul: f64,
    bwselect: String,
    expected: Expected,
}

#[derive(Deserialize)]
struct FixtureBundle {
    schema_version: u32,
    oracle: OracleMetadata,
    cases: Vec<serde_json::Value>,
}

#[derive(Deserialize)]
struct OracleMetadata {
    package: String,
    version: String,
}

fn kernel(s: &str) -> Kernel {
    match s {
        "tri" => Kernel::Triangular,
        "epa" => Kernel::Epanechnikov,
        "uni" => Kernel::Uniform,
        other => panic!("kernel {other}"),
    }
}

fn vce(s: &str) -> Vce {
    match s {
        "hc0" => Vce::Hc0,
        "hc1" => Vce::Hc1,
        "nn" => Vce::NearestNeighbor,
        other => panic!("vce {other}"),
    }
}

fn close(a: f64, b: f64) -> bool {
    (a - b).abs() <= 1e-8 * a.abs().max(b.abs()).max(1.0)
}

#[test]
fn rdbwselect_matches_r() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../fixtures/bandwidth.json");
    let bundle: FixtureBundle = serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
    assert_eq!(bundle.schema_version, 1);
    assert_eq!(bundle.oracle.package, "rdrobust");
    assert_eq!(bundle.oracle.version, "1.3.0");
    let mut n = 0;
    for case in bundle
        .cases
        .into_iter()
        .filter(|case| case["kind"] == "bwselect")
    {
        let f: Fixture = serde_json::from_value(case).unwrap();
        let out = rdbwselect(
            &f.y,
            &f.x,
            f.t.as_deref(),
            None,
            0,
            f.c,
            f.p,
            f.q,
            f.deriv,
            kernel(&f.kernel),
            vce(&f.vce),
            3,
            false,
            f.scaleregul,
            &f.bwselect,
            None,
            None,
            "off",
            false,
            false,
            None,
        );
        assert!(
            close(out.h_l, f.expected.h_l),
            "{} h_l: {} vs R {}",
            f.id,
            out.h_l,
            f.expected.h_l
        );
        assert!(
            close(out.h_r, f.expected.h_r),
            "{} h_r: {} vs R {}",
            f.id,
            out.h_r,
            f.expected.h_r
        );
        assert!(
            close(out.b_l, f.expected.b_l),
            "{} b_l: {} vs R {}",
            f.id,
            out.b_l,
            f.expected.b_l
        );
        assert!(
            close(out.b_r, f.expected.b_r),
            "{} b_r: {} vs R {}",
            f.id,
            out.b_r,
            f.expected.b_r
        );
        n += 1;
    }
    assert!(n >= 8, "expected >= 8 bwselect fixtures, found {n}");
    eprintln!("rdbwselect parity: {n} fixtures matched R to 1e-8");
}
